edits.to:
  .mskba-hero-scene .mskba-hero-slide__layer-scrim--dark {
    background: linear-gradient(90deg, rgba(5, 7, 10, .56), rgba(5, 7, 10, .22) 70%, rgba(5, 7, 10, .12)) !important;
  }
}

/* Hero/arena composition: CSS-first peak, independent mobile layout.
   The existing ball motion and players' easing are intentionally untouched. */
.site-header.app-site-header { z-index: 100 !important; }

@media (min-width: 1100px) {
  /* Max overlap at either jump peak: 18px relative to the Hero bottom. */
  #venues-scene .mskba-v3-venues__defender {
    top: calc(var(--v3-hero-bleed) + clamp(134px, 10.85vw, 185px) - 18px) !important;
    bottom: auto !important;
    width: clamp(375px, 30vw, 530px) !important;
  }
  #venues-scene .mskba-v3-venues__shooter-frame {
    top: calc(var(--v3-hero-bleed) - 18px) !important;
    bottom: auto !important;
    width: clamp(415px, 32.4vw, 575px) !important;
  }
}

@media (max-width: 759px) {
  /* Extend the same Arena background from the start of the mobile Hero. */
  #hero > .container.mt-3 { margin-top: 0 !important; }
  #venues-scene { --v3-hero-bleed: clamp(470px, calc(365px + 21vw), 500px); }
  #venues-scene .mskba-v3-venues__arena {
    width: 100%;
    height: 100%;
    object-fit: cover;
    object-position: center top;
  }
  /* Override legacy visual-space height so the player cutouts are not cropped. */
  #venues-scene .mskba-v3-venues__foreground {
    inset: 0;
    height: auto;
    overflow: hidden;
  }
  #venues-scene .mskba-v3-venues__defender {
    top: 12px;
    bottom: auto !important;
    left: 2%;
    width: clamp(168px, 44vw, 218px);
  }
  #venues-scene .mskba-v3-venues__shooter-frame > .mskba-v3-venues__shooter {
    top: 6px;
    bottom: auto !important;
    left: auto;
    right: 2%;
    width: clamp(188px, 48vw, 242px);
  }
  #venues-scene .mskba-v3-venues__container {
    padding-top: clamp(405px, 105vw, 500px);
  }
  .mskba-hero-scene .mskba-hero-slider {
    background: transparent !important;
    box-shadow: none !important;
  }
  .mskba-hero-scene .mskba-hero-slider__stage,
  .mskba-hero-scene .mskba-hero-slide {
    background: transparent !important;
  }
  .mskba-hero-scene .mskba-hero-slide__background {
    display: none !important;
  }
  .mskba-hero-scene .mskba-hero-slide__layer-scrim--dark {
    background: linear-gradient(180deg, rgba(4, 11, 22, .72), rgba(4, 11, 22, .24) 72%, rgba(4, 11, 22, .08)) !important;
  }
}

@media (min-width: 700px) and (max-width: 759px) {
  /* The Hero uses a fixed 400px height in this breakpoint. */
  #venues-scene { --v3-hero-bleed: 400px; }
}
